mapper.select:
select e.id, e.check_in_place_id, e.serial_number, e.online_status, e.enable_status, e.contact_phone, e.sort, e.remark, e.create_time, e.update_time, e.delete_time, cp.name as check_in_place_name from equipment e left join check_in_place cp on e.check_in_place_id = cp.id
and e.serial_number like concat('%', #{param.keyword}, '%')
and e.online_status = #{param.searchIntStatus}
and cp.check_in_type_id = #{param.searchType}
and cp.name like concat('%', #{param.searchStrField1}, '%')
and e.enable_status = #{param.searchField1}
and e.create_time >= #{param.startTime}
and #{param.endTime} >= e.create_time
and e.delete_time is null

